import urllib.request
import socket
socket.setdefaulttimeout(25)
print('=== ROBOTS ===')
try:
    r=urllib.request.urlopen('https://www.okc.gov/robots.txt')
    print(r.read().decode('latin-1'))
except Exception as e:
    print('robots ERR '+str(e)[:200])
print('=== MANUAL PAGE ===')
try:
    r=urllib.request.urlopen('https://www.okc.gov/Services/Public-Safety/Police/OKCPD-Operations-Manual')
    h=r.read().decode('latin-1')
    print('status '+str(r.status)+' bytes '+str(len(h)))
    for tok in h.split():
        low=tok.lower()
        if '.pdf' in low or 'manual' in low or 'showpublisheddocument' in low:
            print('TOK '+tok[:220])
except Exception as e:
    print('page ERR '+str(e)[:200])
